using System;
using System.Collections.Generic;
namespace RSSG.Core;
public sealed class StarSystemGenerator { public const int CurrentGeneratorVersion=1; static readonly string[] A=["Aster","Cinder","Vesper","Orion","Nexa","Helio","Kestrel","Solara","Draco","Aquila"]; static readonly string[] B=["Reach","Haven","Crown","Drift","Point","Vale","Crossing","Sanctum","Horizon","Gate"]; public GeneratedStarSystem Generate(GenerationSettings s){ArgumentNullException.ThrowIfNull(s);s.Validate();var r=new SeededRandom(s.Seed);string name=$"{Pick(r,A)} {Pick(r,B)}";var stars=new List<Star>();var st=(StarClass)r.NextInt(0,5);stars.Add(MakeStar(r,"STAR-0","Primary",st));if(s.AllowBinaryStars&&r.NextBool(.22))stars.Add(MakeStar(r,"STAR-1","Companion",(StarClass)r.NextInt(0,3)));int n=r.NextInt(s.MinPlanets,s.MaxPlanets+1);var planets=new List<Planet>();double orbit=r.NextDouble(.25,.65);for(int i=0;i<n;i++){orbit*=r.NextDouble(1.35,2.15);var t=(PlanetClass)r.NextInt(0,7);double radius=t==PlanetClass.GasGiant?r.NextDouble(25000,80000):t==PlanetClass.IceGiant?r.NextDouble(12000,30000):r.NextDouble(1800,9000);double gravity=t==PlanetClass.GasGiant?r.NextDouble(.8,2.5):t==PlanetClass.IceGiant?r.NextDouble(.6,1.6):r.NextDouble(.15,1.8);bool atm=t is PlanetClass.GasGiant or PlanetClass.IceGiant||r.NextBool(.68);double temp=35-Math.Log10(Math.Max(orbit,.1))*95+r.NextDouble(-35,35);int mc=s.GenerateMoons?r.NextInt(s.MinMoonsPerPlanet,s.MaxMoonsPerPlanet+1):0;var moons=new List<Moon>();for(int m=0;m<mc;m++)moons.Add(new Moon($"P{i+1}-M{m+1}",$"Moon {i+1}-{m+1}",r.NextDouble(250,4200),r.NextDouble(30000,900000)));planets.Add(new Planet($"PLANET-{i+1}",$"World {i+1}",t,radius,gravity,atm,temp,orbit,moons));}var belts=new List<AsteroidBelt>();if(s.GenerateAsteroidBelts){int bc=r.NextInt(s.MinAsteroidBelts,s.MaxAsteroidBelts+1);for(int i=0;i<bc;i++){double inner=r.NextDouble(.8,Math.Max(1,planets[^1].OrbitalDistanceAu+1));belts.Add(new AsteroidBelt($"BELT-{i+1}",inner,inner+r.NextDouble(.15,.8),r.NextInt(100,5001)));}}return new GeneratedStarSystem(s.Seed,CurrentGeneratorVersion,name,stars,planets,belts);} static Star MakeStar(SeededRandom r,string id,string label,StarClass t){(double a,double b,double c,double d,double e,double f)=t switch{StarClass.RedDwarf=>(.08,.6,.1,.6,2400,3900),StarClass.OrangeDwarf=>(.6,.9,.7,.9,3900,5200),StarClass.YellowDwarf=>(.9,1.1,.9,1.2,5200,6000),StarClass.WhiteStar=>(1.1,2,1.2,2,7500,12000),_=>(8,18,3,8,12000,30000)};return new Star(id,$"{label} {r.NextInt(100,999)}",t,r.NextDouble(a,b),r.NextDouble(c,d),r.NextDouble(e,f));} static string Pick(SeededRandom r,string[] x)=>x[r.NextInt(0,x.Length)]; }